INSERT INTO `evaluation_criteria` (`id`, `evaluator_type`, `target_role`, `criterion_text`, `criterion_text_am`, `category`, `weight`, `is_active`, `created_at`) VALUES
(1, 'student', 'instructor', 'The instructor communicates clearly and supports learning.', 'መምህሩ በግልጽ ይገልጻል እና ትምህርትን ይደግፋል።', 'Teaching', 5, 1, '2026-08-25 07:40:49'),
(2, 'peer', 'instructor', 'The instructor demonstrates professional competence.', 'መምህሩ ሙያዊ ብቃት ያሳያል።', 'Professional Competency', 5, 1, '2026-08-25 07:40:49'),
(3, 'dept_head', 'instructor', 'The instructor fulfills departmental responsibilities.', 'መምህሩ የዲፓርትመንቱን ኃላፊነቶች ይወጣል።', 'Departmental Responsibility', 5, 1, '2026-08-25 07:40:49'),
(4, 'dean', 'instructor', 'The instructor contributes to college goals.', 'መምህሩ ለኮሌጁ ግቦች አስተዋጽኦ ያደርጋል።', 'College Contribution', 5, 1, '2026-08-25 07:40:49'),
(5, 'student', 'instructor', 'Understands the objective and content of the course and comes prepared.', 'የትምህርቱን ዓላማ፣ ይዘት እና ኮርስ አውትላይኑን በግልጽ ያውቃል፤ በጊዜ በሴላበሱ መሠረት አዘጋጅቶ ያቀርባል።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(6, 'student', 'instructor', 'Prepares adequately and delivers lectures according to the outline.', 'ለሚያስተምረው ትምህርት በቂ ዝግጅት አድርጎ በካሪኩለም እና በሴላበስ መሠረት ያቀርባል።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(7, 'student', 'instructor', 'Uses relevant reference materials for the course.', 'ለሚያስተምረው ትምህርት አስፈላጊ የሆኑ መراجعዎችን ይጠቀማል።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(8, 'student', 'instructor', 'Provides useful course outlines and reading lists.', 'ለሚያስተምረው ትምህርት ጠቃሚ የሆኑ በካሪኩለም ውስጥ ያሉ ማጣቀሻ መጻሕፍት ዝርዝር አዘጋጅቶ ለተማሪዎች ይሰጣል።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(9, 'student', 'instructor', 'Uses practical examples, case studies, field visits, etc., as needed.', 'እንደአስፈላጊነቱ የትግባር ልምዶች፣ የላብራቶሪ፣ የፊልድ ጉብኝት፣ Case study ወዘተ ይሰጣል።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(10, 'student', 'instructor', 'Has strong basic knowledge in the teaching subject.', 'በሚያስተምረው ትምህርት ላይ መሰረታዊ በቂ እውቀት አለው።', 'Core Competence', 5, 1, '2026-08-25 10:35:20'),
(11, 'student', 'instructor', 'Presents explanations clearly using modern teaching aids.', 'ትምህርቱን በማብራሪያና ድጋፍ ሰጪ መሳሪያዎችን በመጠቀም በግልጽ ያቀርባል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(12, 'student', 'instructor', 'Uses diverse and interactive teaching methods.', 'የተለያዩ የትምህርት መረጣ ዘዴዎችን በመጠቀም ያስተምራል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(13, 'student', 'instructor', 'Provides useful continuous assessments (class work, assignments, quizzes, etc.).', 'ለትምህርቱ ጠቃሚ የሆኑ ምዘናዎችን (ምሳሌ፡ የክፍል/Class work, Homework, Quiz...etc) ገቢር ያደርጋል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(14, 'student', 'instructor', 'Encourages cooperative learning and group work in class.', 'በመተባበር መማር (Cooperative Learning) አደረጃጀት ወይም የቡድን ስራ በክፍል ውስጥ እንዲተገበር ያደርጋል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(15, 'student', 'instructor', 'Evaluates continuous assessments correctly and gives timely feedback.', 'ተከታታይ ምዘናዎችን በትክክልና በኣግባቡ ይገመግማል፤ የተከታታይ ምዘና ውጤቶችን በወቅቱ መልስ በጽሁፍ እና በቃል ይሰጣል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(16, 'student', 'instructor', 'Provides academic support for low-performing students.', 'በተከታታይ ምዘና ውጤት መሠረት በትምህርታቸው ዝቅተኛ ውጤት ላመጡ ተማሪዎች ድጋፍና ፈተና ይሰጣል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(17, 'student', 'instructor', 'Provides assistance for students needing special support.', 'ለሴት ተማሪዎች፣ አካል ጉዳተኞች እና ልዩ ድጋፍ ለሚሹ ተማሪዎች አዎንታዊ አመለካከትና ተገቢውን ድጋፍ ይሰጣል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(18, 'student', 'instructor', 'Asks balanced and clear exam questions based on course objectives.', 'የፈተና ጥያቄዎችን ከአጠቃላይ ትምህርቱ ጋር አዛምዶ ያዘጋጃል፤ ሚዛናዊ የሆኑ የክብደት ደረጃዎችን ያካተተ ፈተና ያዘጋጃል።', 'Professional Competence', 5, 1, '2026-08-25 10:35:20'),
(19, 'student', 'instructor', 'Respects and values students appropriately.', 'ለተማሪዎች ተገቢውን ክብር ይሰጣል።', 'Ethical Competence', 5, 1, '2026-08-25 10:35:20'),
(20, 'student', 'instructor', 'Accepts student questions politely and addresses them in class.', 'በክፍል ውስጥ የተማሪዎችን ጥያቄ ተቀብሎ በኣግባቡ ያስተናግዳል፤ በክፍል ውስጥ ተማሪዎች አስተያየታቸውን በነፃነት እንዲገልፁ ይፈቅዳል።', 'Ethical Competence', 5, 1, '2026-08-25 10:35:20'),
(21, 'student', 'instructor', 'Is punctual, non-biased, and active in instructional duties.', 'በስነ-ስርዓት አከባበር፣ በምዘናው ጨዋታ፣ አወንታዊ ስነ-ምግባርና ፍላጎት አለው።', 'Ethical Competence', 5, 1, '2026-08-25 10:35:20'),
(22, 'student', 'instructor', 'Treats all students equally regardless of sex, religion, etc.', 'በዘር፣ በሃይማኖት፣ በፆታ ልዩነት ሳይያደርግ ሁሉንም በአኩል ያያል።', 'Ethical Competence', 5, 1, '2026-08-25 10:35:20'),
(23, 'student', 'instructor', 'Respects class periods and arrives on time.', 'በተመደበበት የትምህርት ክፍለ ጊዜ ሰዓት አክብሮ ይገኛል፤ ክፍሉን በአግባቡ ያስተምራል።', 'Time Management', 5, 1, '2026-08-25 10:35:20'),
(24, 'student', 'instructor', 'Knows consultation hours and assists students during those times.', 'ተማሪዎችን ለመርዳት የማማከር ሰዓት መድቦ ያውቃል፤ በመደብ አጋጣሚዎች ችግር ለሚያቀርቡ መፍትሄ ይፈልጋል።', 'Time Management', 5, 1, '2026-08-25 10:35:20'),
(25, 'peer', 'instructor', 'Contribution in preparing and searching for teaching materials', 'ለትምህርት ማስተማሪያ ቁሳቁሶች ዝግጅት እና ፍለጋ የሚያደርገው አስተዋጽኦ', 'Subject Matter Competency', 5, 1, '2026-08-25 10:35:20'),
(26, 'peer', 'instructor', 'Continuous update of the subject matter knowledge', 'የትምህርት ክፍሉን እውቀት በቀጣይነት የማሻሻልና የማዘመን ጥረት', 'Subject Matter Competency', 5, 1, '2026-08-25 10:35:20'),
(27, 'peer', 'instructor', 'Delivering seminars that are relevant to his/her teaching subject', 'ከሚያስተምረው ትምህርት ጋር ተዛማጅ የሆኑ ሴሚናሮችን የማቅረብ ብቃት', 'Subject Matter Competency', 5, 1, '2026-08-25 10:35:20'),
(28, 'peer', 'instructor', 'Level of his/her subject matter knowledge and skills', 'በሚያስተምረው የትምህርት ዘርፍ ያለው የእውቀትና የክህሎት ደረጃ', 'Subject Matter Competency', 5, 1, '2026-08-25 10:35:20'),
(29, 'peer', 'instructor', 'Willingness and level of engagement in community service and volunteer activities', 'በማህበረሰብ አገልግሎትና በበጎ ፍቃድ ስራዎች ላይ ያለው ተሳትፎና ፍላጎት', 'Research & Community Services', 5, 1, '2026-08-25 10:35:20'),
(30, 'peer', 'instructor', 'Participation on seminars/workshops at department/faculty/institution level during the year', 'በዲፓርትመንት/በፋከልቲ ደረጃ በሴሚናሮችና ワークሾፖች ላይ ያደረገው ተሳትፎ', 'Research & Community Services', 5, 1, '2026-08-25 10:35:20'),
(31, 'peer', 'instructor', 'Identifying priority areas in discipline, pursuing research and assisting colleagues in proposals', 'በምርምር ዘርፍ ቅድሚያ የሚሰጣቸውን አውዶች በመለየት ምርምር የማድረግና ባልደረቦችን የመደገፍ ፍላጎት', 'Research & Community Services', 5, 1, '2026-08-25 10:35:20'),
(32, 'peer', 'instructor', 'Guidance and counseling role to students', 'ለተማሪዎች የሚያደርገው የምክርና የምክር አገልግሎት (Guidance & Counseling) ድጋፍ', 'Professional Competency', 5, 1, '2026-08-25 10:35:20'),
(33, 'peer', 'instructor', 'Contributing constructive ideas and activities that improve teaching-learning process', 'የመማር ማስተማር ሂደቱን የሚያሻሽሉ ግንባታ ያላቸው ሃሳቦችንና እንቅስቃሴዎችን ማቅረብ', 'Professional Competency', 5, 1, '2026-08-25 10:35:20'),
(34, 'peer', 'instructor', 'Participation in problem identification and solving at department/college/institution level', 'በችግር ለይታና መፍትሄ አሰጣጥ ላይ በዲፓርትመንት/ኮሌጅ ደረጃ ያለው ተሳትፎ', 'Professional Competency', 5, 1, '2026-08-25 10:35:20'),
(35, 'peer', 'instructor', 'Participation in Comprehensive Continuous Professional Development (CCPD, HDP, ELIP)', 'በሙያ ማሻሻያ ስልጠናዎች (CCPD, HDP, ELIP) ላይ ያለው ተሳትፎ', 'Professional Competency', 5, 1, '2026-08-25 10:35:20'),
(36, 'peer', 'instructor', 'Willingness to actively participate in cooperative learning and team teaching activities', 'በተባባሪ መማርና በቡድን ማስተማር (Team Teaching) ስራዎች ላይ ለመሳተፍ ያለው ዝግጁነት', 'Professional Competency', 5, 1, '2026-08-25 10:35:20'),
(37, 'peer', 'instructor', 'Willingness to participate and level of commitment in committee works', 'በኮሚቴ ስራዎች ላይ ለመሳተፍ ያለው ፍላጎትና የተግባር ቁርጠኝነት', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(38, 'peer', 'instructor', 'Willingness to share university resources with other colleagues', 'የዩኒቨርሲቲውን ሃብቶች ከሌሎች ባልደረቦች ጋር በጋራ ለመጠቀም ያለው ፈቃደኝነት', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(39, 'peer', 'instructor', 'Showing cordiality to others, respecting ideas of others', 'ለሌሎች አክብሮት ማሳየትና የሌሎችን ሃሳብ ማክበር', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(40, 'peer', 'instructor', 'Having positive attitude to work with others (team spirit)', 'ከሌሎች ጋር አብሮ ለመስራት ያለው አዎንታዊ አመለካከት (Team Spirit)', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(41, 'peer', 'instructor', 'Level of respect to rules, regulations and guidelines of the institution', 'ለተቋሙ ህጎች፣ ደንቦችና መመሪያዎች ያለው የክብረት ደረጃ', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(42, 'peer', 'instructor', 'His/her discipline (dressing, addictions, personality etc.)', 'የግል ስነ-ምግባሩ (አለባበስ፣ ከሱስ ነፃ መሆን፣ ስብዕና ወዘተ)', 'Ethical Competency', 5, 1, '2026-08-25 10:35:20'),
(43, 'peer', 'instructor', 'Time management in department affairs and in teaching learning activities', 'በዲፓርትመንት ጉዳዮችና በመማር ማስተማር ስራዎች ላይ ያለው የሰዓት አጠቃቀም', 'Time Management', 5, 1, '2026-08-25 10:35:20'),
(44, 'peer', 'instructor', 'Time utilization for consultation hours', 'ለተማሪዎች በተመደበ የማማከሪያ ሰዓት (Consultation hours) ላይ ያለው የሰዓት አጠቃቀም', 'Time Management', 5, 1, '2026-08-25 10:35:20'),
(45, 'dept_head', 'instructor', 'Fulfills department course coverage, continuous assessment submission, and grading deadlines.', 'የኮርስ ሽፋን፣ የተከታታይ ምዘና እና የምዘና ውጤት የማስረከቢያ ጊዜ ገደቦችን ማክበር።', 'Departmental Responsibility', 5, 1, '2026-08-25 10:35:20'),
(46, 'dept_head', 'instructor', 'Active participation in department meetings, curriculum review, and committee duties.', 'በዲፓርትመንት ስብሰባዎች፣ በካሪኩለም ክለሳ እና በኮሚቴ ስራዎች ላይ ንቁ ተሳትፎ ማድረግ።', 'Administrative Engagement', 5, 1, '2026-08-25 10:35:20'),
(47, 'dept_head', 'instructor', 'Adherence to institutional rules, professional ethics, and student guidance quality.', 'የተቋሙን ደንቦች ማክበር፣ ሙያዊ ስነ-ምግባር እና ለተማሪዎች የሚሰጠው የምክር ድጋፍ ጥራት።', 'Professional Conduct', 5, 1, '2026-08-25 10:35:20'),
(48, 'dean', 'instructor', 'Contributes to college-level strategic plans, research output, and community service projects.', 'በኮሌጅ ደረጃ ስትራቴጂካዊ እቅዶች፣ የምርምር ውጤቶች እና በማህበረሰብ አገልግሎት ላይ ማበርከት።', 'College Contribution', 5, 1, '2026-08-25 10:35:20'),
(49, 'dean', 'instructor', 'Demonstrates institutional leadership, resource conservation, and policy compliance.', 'ተቋማዊ አመራር፣ የሀብት ቁጠባ እና ፖሊሲዎችን ማክበር ማሳየት።', 'Institutional Leadership', 5, 1, '2026-08-25 10:35:20'),
(50, 'student', 'lab_assistant', 'Explains detailed objectives of each session', 'የእያንዳንዱን ክፍለ ጊዜ ዝርዝር ዓላማዎች ያብራራል', 'Practical Teaching', 5, 1, '2026-09-01 11:42:04'),
(51, 'student', 'lab_assistant', 'Prepares well for course delivery', 'ለትምህርቱ አሰጣጥ በጥሩ ሁኔታ ይዘጋጃል', 'Preparation', 5, 1, '2026-09-01 11:42:04'),
(52, 'student', 'lab_assistant', 'Teaches as per the course content', 'በትምህርቱ ይዘት መሠረት ያስተምራል', 'Course Delivery', 5, 1, '2026-09-01 11:42:04'),
(53, 'student', 'lab_assistant', 'Prepares well for practical sessions', 'ለተግባራዊ (የላብራቶሪ/ወርክሾፕ) ክፍለ ጊዜዎች በጥሩ ሁኔታ ይዘጋጃል', 'Practical Preparation', 5, 1, '2026-09-01 11:42:04'),
(54, 'student', 'lab_assistant', 'Delivers the course in such a way that the students understand', 'ተማሪዎች በሚረዱት መንገድ ትምህርቱን ያቀርባል', 'Teaching Quality', 5, 1, '2026-09-01 11:42:04'),
(55, 'student', 'lab_assistant', 'Use of additional teaching aids', 'ተጨማሪ የማስተማሪያ ረዳት መሣሪያዎችን ይጠቀማል', 'Teaching Aids', 5, 1, '2026-09-01 11:42:04'),
(56, 'student', 'lab_assistant', 'Answers questions raised by students', 'በተማሪዎች ለሚነሱ ጥያቄዎች ምላሽ ይሰጣል', 'Interaction', 5, 1, '2026-09-01 11:42:04'),
(57, 'student', 'lab_assistant', 'Uses student centered approach such as cooperative army, group work/presentations etc', 'ተማሪን ማዕከል ያደረጉ አቀራረቦችን (የቡድን ሥራ፣ ገለጻ ወዘተ) ይጠቀማል', 'Teaching Method', 5, 1, '2026-09-01 11:42:04'),
(58, 'student', 'lab_assistant', 'Gives respect to students', 'ለተማሪዎች አክብሮት ይሰጣል', 'Ethics & Behavior', 5, 1, '2026-09-01 11:42:04'),
(59, 'student', 'lab_assistant', 'Allows students to interact during class room', 'በክፍል ውስጥ ተማሪዎች እንዲሳተፉ እና እንዲወያዩ ይፈቅዳል', 'Interaction', 5, 1, '2026-09-01 11:42:04'),
(60, 'student', 'lab_assistant', 'Listens to students problems', 'የተማሪዎችን ችግሮች ያዳምጣል', 'Support', 5, 1, '2026-09-01 11:42:04'),
(61, 'student', 'lab_assistant', 'Ethics, behavior and commitment for knowledge transfer', 'ሥነ-ምግባር፣ ጠባይ እና እውቀትን ለማስተላለፍ ያለው ቁርጠኝነት', 'Ethics & Commitment', 5, 1, '2026-09-01 11:42:04'),
(62, 'student', 'lab_assistant', 'Impartiality based on ethnic, religion or gender', 'በብሔር፣ በሃይማኖት ወይም በፆታ ልዩነት ሳያደርግ በግልጽነትና በነጻነት ያስተናግዳል', 'Fairness', 5, 1, '2026-09-01 11:42:04'),
(63, 'student', 'lab_assistant', 'Use class beginning and ending time appropriately', 'የክፍል መግቢያና መውጫ ሰዓትን በትክክል ይጠቀማል', 'Punctuality', 5, 1, '2026-09-01 11:42:04'),
(64, 'student', 'lab_assistant', 'Use class time appropriately', 'የክፍል ጊዜውን በአግባቡ ይጠቀማል', 'Time Management', 5, 1, '2026-09-01 11:42:04'),
(65, 'student', 'lab_assistant', 'Gives time for practical sessions', 'ለተግባራዊ ልምምዶች በቂ ጊዜ ይሰጣል', 'Practical Focus', 5, 1, '2026-09-01 11:42:04'),
(66, 'student', 'lab_assistant', 'Solves students academic problems on time', 'የተማሪዎችን አካዳሚያዊ ችግሮች በጊዜው ይፈታል', 'Problem Solving', 5, 1, '2026-09-01 11:42:04'),
(67, 'peer', 'lab_assistant', 'Continuous update of the subject matter', 'የሚያስተምረውን/የሚሰራበትን የትምህርት ዘርፍ እውቀት ሁልጊዜ ያሻሽላል', 'Professional Competency', 5, 1, '2026-09-01 11:42:04'),
(68, 'peer', 'lab_assistant', 'Level of his/her subject matter knowledge and practical skill', 'ያለው የትምህርት ዘርፍ እውቀት እና የተግባር ክህሎት ደረጃ', 'Practical Skill', 5, 1, '2026-09-01 11:42:04'),
(69, 'peer', 'lab_assistant', 'Participation in seminars/workshop/research at department/college/university level during the year', 'በሴሚናር፣ ወርክሾፕ እና ምርምሮች ላይ የሚያደርገው ተሳትፎ', 'Research & Seminar', 5, 1, '2026-09-01 11:42:04'),
(70, 'peer', 'lab_assistant', 'Guidance and counseling role to students during practical sessions', 'በተግባር ክፍለ ጊዜዎች ለተማሪዎች የሚሰጠው የምክር እና የመሪነት ሚና', 'Student Guidance', 5, 1, '2026-09-01 11:42:04'),
(71, 'peer', 'lab_assistant', 'Assist faculty and students in the analysis of samples, maintenance, upkeep of instruments facilities, and general supervision', 'በናሙና ምርመራ፣ መሣሪያዎችን በመንከባከብ እና በክትትል መምህራንን እና ተማሪዎችን ያግዛል', 'Lab Maintenance & Support', 5, 1, '2026-09-01 11:42:04'),
(72, 'peer', 'lab_assistant', 'Contributing ideas and activities that improve the teaching learning process', 'የመማር ማስተማር ሂደቱን የሚያሻሽሉ ሃሳቦችን እና እንቅስቃሴዎችን ያበረክታል', 'Innovation', 5, 1, '2026-09-01 11:42:04'),
